// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    receive() external payable {}

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, type(uint128).max);
        // fund the contract directly with an arbitrary amount (depositsCount stays 0)
        vm.deal(address(c), amount);
        // owner (the test contract, which deployed c) withdraws everything
        c.withdrawAll();
        // Rule: withdrawAll always empties the contract balance.
        // Reference: transfers address(this).balance -> balance 0.
        // Mutant: transfers depositsCount (0) -> balance stays `amount` (> 0).
        assertTrue(address(c).balance == 0);
    }
}
